[{"path": "research/code-analysis-skill-evolution-v1-20261107/materials/U1/candidate/src/progress-source.js", "lines": "26-30", "quote": "    start() {
      const packet = typeof initialPacket === "function" ? initialPacket() : initialPacket;
      if (packet !== undefined) target.dispatchEvent(new ProgressEvent(packet));
    },
    emit(packet) { target.dispatchEvent(new ProgressEvent(packet)); },"}, {"path": "research/code-analysis-skill-evolution-v1-20261107/materials/U1/candidate/src/progress.js", "lines": "3-10", "quote": "  const listener = event => {
    const deliver = frame => { record(frame); receive(frame); };
    const decoded = feed.decode(event.detail);
    if (decoded && typeof decoded.then === "function") decoded.then(deliver);
    else deliver(decoded);
  };
  feed.start();
  feed.target.addEventListener("progress", listener);"}]

[{"path": "research/code-analysis-skill-evolution-v1-20261107/materials/U1/candidate/src/progress.js", "lines": "4-7", "quote": "    const deliver = frame => { record(frame); receive(frame); };
    const decoded = feed.decode(event.detail);
    if (decoded && typeof decoded.then === "function") decoded.then(deliver);
    else deliver(decoded);"}, {"path": "research/code-analysis-skill-evolution-v1-20261107/materials/U1/candidate/README.md", "lines": "10-12", "quote": "The feed object is shared by attempts and visits for that file. Its `start()`
method may synchronously emit cached data, and `decode(packet)` may return a
value or a Promise."}]

[{"path": "research/code-analysis-skill-evolution-v1-20261107/materials/U1/candidate/src/progress.js", "lines": "3-11", "quote": "  const listener = event => {
    const deliver = frame => { record(frame); receive(frame); };
    const decoded = feed.decode(event.detail);
    if (decoded && typeof decoded.then === "function") decoded.then(deliver);
    else deliver(decoded);
  };
  feed.start();
  feed.target.addEventListener("progress", listener);
  return () => feed.target.removeEventListener("progress", listener);"}, {"path": "research/code-analysis-skill-evolution-v1-20261107/materials/U1/candidate/src/queue.js", "lines": "11-15", "quote": "  const progress = {
    record(frame) { state.recordProgress({ fileId: visit.file.id, attemptId, frame }); },
    receive(frame) {
      if (state.current === visit) state.showProgress({ fileId: visit.file.id, attemptId, frame });
    },"}]

