      if (state.current === visit) state.showProgress({ fileId: visit.file.id, attemptId, frame });
    },"}]

[{"path": "research/code-analysis-skill-evolution-v1-20261107/materials/U1/candidate/src/transfer.js", "lines": "5-13", "quote": "  let stopProgress = () => {};
  controller.signal.addEventListener("abort", () => {
    stopProgress();
    onCancel({ file, attemptId, signal: controller.signal });
  }, { once: true });
  transport({ file, attemptId, signal: controller.signal });
  if (file.progressFeed) {
    stopProgress = watchTransferProgress(file.progressFeed, progress.receive, progress.record);
    if (controller.signal.aborted) stopProgress();"}, {"path": "research/code-analysis-skill-evolution-v1-20261107/materials/U1/candidate/src/progress.js", "lines": "11-11", "quote": "  return () => feed.target.removeEventListener("progress", listener);"}, {"path": "research/code-analysis-skill-evolution-v1-20261107/materials/U1/candidate/src/panel.js", "lines": "4-7", "quote": "export function releaseVisit(visit) {
  const handle = visit.handle;
  visit.handle = null;
  if (handle) handle.cancel();"}]

[{"path": "research/code-analysis-skill-evolution-v1-20261107/materials/U1/candidate/src/progress.js", "lines": "9-11", "quote": "  feed.start();
  feed.target.addEventListener("progress", listener);
  return () => feed.target.removeEventListener("progress", listener);"}, {"path": "research/code-analysis-skill-evolution-v1-20261107/materials/U1/candidate/src/transfer.js", "lines": "5-16", "quote": "  let stopProgress = () => {};
  controller.signal.addEventListener("abort", () => {
    stopProgress();
    onCancel({ file, attemptId, signal: controller.signal });
  }, { once: true });
  transport({ file, attemptId, signal: controller.signal });
  if (file.progressFeed) {
    stopProgress = watchTransferProgress(file.progressFeed, progress.receive, progress.record);
    if (controller.signal.aborted) stopProgress();
  }
  return { file, attemptId, signal: controller.signal,
    cancel() { if (!controller.signal.aborted) controller.abort(); } };"}, {"path": "research/code-analysis-skill-evolution-v1-20261107/materials/U1/candidate/src/panel.js", "lines": "17-25", "quote": "  const visit = { id: requestId, file, handle: null };
  state.current = visit;
  const handle = enqueueTransfer(state, visit, "select");
  if (state.current === visit) {
    visit.handle = handle;
    publishQueued(state, visit, handle);
  } else {
    handle.cancel();
  }"}]

